SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"follow_up_duration_for_primary_endpoint_s_in_months_rx\" AS rx_months, \"follow_up_duration_for_primary_endpoint_s_in_months_control\" AS control_months FROM public.\"clinical_trials\" WHERE \"cancer_type\" = 'Melanoma' ORDER BY \"follow_up_duration_for_primary_endpoint_s_in_months_rx\" ASC, \"follow_up_duration_for_primary_endpoint_s_in_months_control\" ASC;